def _read_raw_body(self) -> bytes | None:
    length_header = self.headers.get("Content-Length")
    if length_header is None:
        return None
    try:
        length = int(length_header)
    except ValueError:
        return None
    if length <= 0:
        return None
    return self.rfile.read(length)

def _read_json_object(
    self, body: bytes | None = None, *, unbounded_ints: bool = False
) -> dict[str, Any] | None:
    if body is None:
        body = self._read_raw_body()
        if body is None:
            return None
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        return None
    try:
        # 任意长度整数仅限审计序号入口；其他入口保留全局转换保护。
        parsed = json.loads(
            text,
            object_pairs_hook=_unique_object,
            parse_int=_audit_json_int if unbounded_ints else int,
        )
    except ValueError:
        return None
    if not isinstance(parsed, dict):
        return None
    return parsed

def _audit_idempotency_key(self) -> str | None:
    # 审计写入口要求恰好一个合法 Idempotency-Key：缺失、重复或格式非法
    # 均为 400/invalid_request，且不查询任何资源。
    values = self.headers.get_all("Idempotency-Key")
    if values is None or len(values) != 1:
        return None

def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    keys = [key for key, _ in pairs]
    if len(set(keys)) != len(keys):
        raise ValueError("duplicate object member")
    return dict(pairs)


def _bounded_int(value: Any, minimum: int, maximum: int) -> bool:
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and minimum <= value <= maximum
    )


def _positive_int(value: Any) -> bool:
    # 任意非布尔正整数：不设数据库整数上界，超范围值交由存在性查询按缺失处理。
    return isinstance(value, int) and not isinstance(value, bool) and value >= 1


def _decimal_int(text: str) -> int | None:
    # 进程级整数转换保护（PEP 682）下，超过位数上限的十进制文本折叠为 None：
    # 调用方按既有非法/不存在语义拒绝（400 或 404），连接保持可用。
    try:
        return int(text)
    except ValueError:
        return None


def _audit_json_int(text: str) -> int:
    # 审计序号接受任意长度合法整数：超出全局 int↔str 位数保护的值折叠为
    # 超存储范围哨兵，由存在性判定按缺失处理（404/not_found）；
    # 不关闭全局转换保护，也不让解析异常断连。
    try:
        return int(text)
    except ValueError:
        return INT64_MAX + 1 if not text.startswith("-") else -1


class Handler(BaseHTTPRequestHandler):
    server: ApiServer

    def _json(self, status: HTTPStatus, payload: dict[str, Any]) -> None:
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:  # noqa: N802
        target = urlsplit(self.path)
        if target.path == "/health":
            with closing(connect(self.server.database_path)) as database:
                version = database.execute(
                    "SELECT value FROM schema_metadata WHERE key = 'schema_version'"
                ).fetchone()[0]
            self._json(
                HTTPStatus.OK,
                {
                    "status": "ok",
                    "service": "service-sla-settlement-network",
                    "schemaVersion": version,
                    "time": datetime.now(UTC).isoformat(),
                },
            )
            return
        telemetry_match = SLA_TELEMETRY_PATH_PATTERN.fullmatch(target.path)
        if telemetry_match is not None:
            self._get_telemetry(telemetry_match.group(1), target.query)
            return
        telemetry_seal_match = SLA_TELEMETRY_SEAL_PATH_PATTERN.fullmatch(target.path)
        if telemetry_seal_match is not None:
            self._get_telemetry_seal(telemetry_seal_match.group(1), target.query)
            return
        telemetry_batch_match = TELEMETRY_BATCH_ITEM_PATH_PATTERN.fullmatch(
            target.path
        )
        if telemetry_batch_match is not None:
            self._get_telemetry_batch(telemetry_batch_match.group(1), target.query)
            return
        machine_delegations_match = MACHINE_DELEGATIONS_PATH_PATTERN.fullmatch(
            target.path
        )
        if machine_delegations_match is not None:
            self._get_machine_delegations(
                machine_delegations_match.group(1), target.query
            )
            return
        delegation_consumptions_match = (
            MACHINE_DELEGATION_CONSUMPTIONS_PATH_PATTERN.fullmatch(target.path)
        )
        if delegation_consumptions_match is not None:
            self._get_delegation_consumptions(
                delegation_consumptions_match.group(1), target.query
            )
            return
        delegation_events_match = DELEGATION_EVENTS_PATH_PATTERN.fullmatch(target.path)
        if delegation_events_match is not None:
            self._get_delegation_events(
                delegation_events_match.group(1), target.query
            )
            return
        evaluations_match = SLA_EVALUATIONS_PATH_PATTERN.fullmatch(target.path)
        if evaluations_match is not None:
            self._get_evaluations(evaluations_match.group(1), target.query)
            return
        evaluation_batch_match = EVALUATION_BATCH_ITEM_PATH_PATTERN.fullmatch(
            target.path
        )
        if evaluation_batch_match is not None:
            self._get_evaluation_batch(
                evaluation_batch_match.group(1), target.query
            )
            return
        settlements_match = SLA_SETTLEMENTS_PATH_PATTERN.fullmatch(target.path)
        if settlements_match is not None:
            self._get_settlements(settlements_match.group(1), target.query)

class TelemetrySealTests(unittest.TestCase):
    def setUp(self) -> None:
        self.temporary = tempfile.TemporaryDirectory()
        self.server = ApiServer(("127.0.0.1", 0), Handler)
        self.server.database_path = str(Path(self.temporary.name) / "service.db")
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()
        self.machine_id = machine_id(PUBLIC_KEY_A)
        self.consumer_id = machine_id(PUBLIC_KEY_B)
        for key, public_key in (("register-1", PUBLIC_KEY_A), ("register-2", PUBLIC_KEY_B)):
            request = Request(
                self.url("/v1/machines"),
                data=json.dumps({"publicKey": public_key}).encode(),
                method="POST",
            )
            request.add_header("Idempotency-Key", key)
            with urlopen(request, timeout=5) as response:
                self.assertEqual(response.status, 201)
        request = Request(
            self.url(f"/v1/machines/{self.machine_id}/capabilities"),
            data=json.dumps(
                {
                    "expectedVersion": 0,
                    "name": "pump-01",
                    "protocol": "mqtt",
                    "region": "cn",
                    "unit": "call",
                    "capacity": 10,
                }
            ).encode(),
            method="POST",
        )
        request.add_header("Idempotency-Key", "cap-1")
        add_sla_auth(request, self.server)
        with urlopen(request, timeout=5) as response:
            self.assertEqual(response.status, 201)
        request = Request(
            self.url("/v1/sla-templates"),
            data=json.dumps(
                {
                    "id": "tpl-1",
                    "machineId": self.machine_id,
                    "capabilityVersion": 1,
                    "priceMicros": 1000,
                    "maxLatencyMs": 50,
                }
            ).encode(),
            method="POST",
        )
        request.add_header("Idempotency-Key", "tpl-1")
        with urlopen(request, timeout=5) as response:
            self.assertEqual(response.status, 201)
        current = int(time.time())
        self.start = current - 10
        self.end = current + 3600
        self.create_sla("sla-1", "sla-create-1")

    def tearDown(self) -> None:
        self.server.shutdown()
        self.server.server_close()
        self.thread.join(timeout=2)
        self.temporary.cleanup()

    def url(self, path: str) -> str:
        return f"http://127.0.0.1:{self.server.server_port}{path}"

    def create_sla(self, sla_id: str, key: str) -> None:
        request = Request(
            self.url("/v1/slas"),
            data=json.dumps(
                {
                    "id": sla_id,
                    "templateId": "tpl-1",
                    "consumerId": self.consumer_id,
                    "start": self.start,
                    "end": self.end,
                }
            ).encode(),
            method="POST",
        )
        request.add_header("Idempotency-Key", key)
        with urlopen(request, timeout=5) as response:
            self.assertEqual(response.status, 201)

    def activate(self, sla_id: str = "sla-1") -> None:
        for index, (party, actor) in enumerate(
            (
                ("producer", self.machine_id),
                ("consumer", self.consumer_id),
            )
        ):
            request = Request(
                self.url(f"/v1/slas/{sla_id}/confirmations"),
                data=json.dumps({"party": party, "actorId": actor}).encode(),
                method="POST",
            )
            request.add_header("Idempotency-Key", f"conf-{sla_id}-{index}")
            add_sla_auth(request, self.server)
            with urlopen(request, timeout=5) as response:
                self.assertEqual(response.status, 200)

    def expire(self, sla_id: str = "sla-1") -> None:
        # 直接把结束时刻改到过去（start+5 秒），使 SLA 满足封存时间条件；
        # 窗口内已提交的事件（start+0.1s 起）仍位于新区间内。
        connection = sqlite3.connect(self.server.database_path)
        try:
            connection.execute(
                "UPDATE slas SET end_unix = ? WHERE id = ?",
                (self.start + 5, sla_id),
            )
            connection.commit()
        finally:
            connection.close()

    def digest(self, sla_id: str, event_id: str, timestamp: int, latency_ms: int) -> str:
        message = f"{sla_id}\n{event_id}\n{timestamp}\n{latency_ms}\n{self.machine_id}"
        return hashlib.sha256(message.encode("utf-8")).hexdigest()

    def add_event(
        self, index: int, timestamp: int, latency_ms: int, sla_id: str = "sla-1"
    ) -> tuple[int, bytes]:
        event_id = f"evt-{index:03d}"
        digest = self.digest(sla_id, event_id, timestamp, latency_ms)
        body = json.dumps(
            {
                "eventId": event_id,
                "timestamp": timestamp,
                "latencyMs": latency_ms,
                "digest": digest,
                "keyVersion": 1,
                "signature": telemetry_signature(
                    PRODUCER_SEED, sla_id, event_id, timestamp, latency_ms, digest,
                    self.machine_id,
                ),
            }
        ).encode()
        request = Request(
            self.url(f"/v1/slas/{sla_id}/telemetry"), data=body, method="POST"
        )
        request.add_header("Idempotency-Key", f"tel-{sla_id}-{index}")
        try:
            with urlopen(request, timeout=5) as response:
                return response.status, response.read()
        except HTTPError as error:
            return error.code, error.read()

    def seal_body(self, actor: str | None = None) -> bytes:
        if actor is None:
            actor = self.machine_id
        return json.dumps({"actorId": actor}).encode()

    def post_seal(
        self,
        body: bytes | None = None,
        sla_id: str = "sla-1",
        idempotency_key: str | None = "seal-1",
        query: str = "",
        auth: str | None = None,
        extra_headers: dict[str, str] | None = None,
    ) -> tuple[int, bytes]:
        if body is None:
            body = self.seal_body()
        suffix = f"?{query}" if query else ""
        path = f"/v1/slas/{sla_id}/telemetry-seals"
        request = Request(self.url(f"{path}{suffix}"), data=body, method="POST")
        if idempotency_key is not None:
            request.add_header("Idempotency-Key", idempotency_key)
        if auth is None:
            add_sla_auth(request, self.server)
        else:
            request.add_header("SLA-Auth", auth)
        for name, value in (extra_headers or {}).items():
            request.add_header(name, value)
        try:
            with urlopen(request, timeout=5) as response:
                return response.status, response.read()
        except HTTPError as error:
            return error.code, error.read()

    def get_seal(
        self, sla_id: str = "sla-1", query: str = ""
    ) -> tuple[int, bytes]:
        suffix = f"?{query}" if query else ""
        try:
            with urlopen(
                self.url(f"/v1/slas/{sla_id}/telemetry-seal{suffix}"), timeout=5
            ) as response:
                return response.status, response.read()
        except HTTPError as error:
            return error.code, error.read()

    def get_sla_state(self, sla_id: str = "sla-1") -> str:
        with urlopen(self.url(f"/v1/slas/{sla_id}"), timeout=5) as response:
            return json.loads(response.read())["state"]

    def restart(self) -> None:
        self.server.shutdown()
        self.server.server_close()
        self.thread.join(timeout=2)
        self.server = ApiServer(("127.0.0.1", 0), Handler)
        self.server.database_path = str(Path(self.temporary.name) / "service.db")
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()

    def test_seal_success_response_and_state(self) -> None:
        self.activate()
        base = self.start * 1000
        self.assertEqual(self.add_event(1, base + 100, 10)[0], 201)
        self.assertEqual(self.add_event(2, base + 200, 60)[0], 201)
        self.expire()

